// spec: specs/search-prefs.md 1.3 · кейс .qa/tests/search-prefs/PREF-02.md
// Меняет предпочтения free (возраст) → @data; исходные значения возвращаются в finally (REST, токеном free).
import { test, expect } from '@playwright/test';
import path from 'path';
import { openPrefs, ageValues, dragHandleTo } from './prefs-helpers';
import { restGet, type Api, type Row } from '../_shared/api';
import type { Page, Request } from '@playwright/test';
import { saveSession } from '../_shared/session';

// Мышью в Chromium с шириной телефона (в эмуляции iPhone мышь не двигает ручки; проект data — Chromium).
test.use({ storageState: path.resolve(__dirname, '../../../auth/free.json'), viewport: { width: 390, height: 844 } });

async function apiFrom(page: Page, req: Request): Promise<Api> {
  const h = await req.allHeaders();
  const payload = JSON.parse(Buffer.from(h['authorization'].split(' ')[1].split('.')[1], 'base64url').toString('utf8'));
  return { page, base: req.url().split('/rest/v1/')[0], apikey: h['apikey'], auth: h['authorization'], userId: String(payload.sub) };
}

const KEYS = ['pref_age_min', 'pref_age_max', 'pref_distance_km', 'interested_in'] as const;

test.describe('העדפות חיפוש — сохранение', () => {
  test('узкий диапазон 34–35 сохраняется: PATCH, «נשמר», после перезагрузки 34–35 @iphone @data (#3872fc)', async ({ page }) => {
    // Токен и адрес API — из настоящего запроса экрана (без лишнего перехода: повторная загрузка ломает захват ручки мышью).
    const apiReq = page.waitForRequest((r) => {
      const h = r.headers();
      return r.url().includes('/rest/v1/') && !!h['apikey'] && !!h['authorization'] && h['authorization'] !== `Bearer ${h['apikey']}`;
    });
    await openPrefs(page);
    const api = await apiFrom(page, await apiReq);
    const before: Row = (await (await restGet(api, `profiles?id=eq.${api.userId}&select=${KEYS.join(',')}`)).json())[0];
    try {
      await dragHandleTo(page, 'max', 60);
      await dragHandleTo(page, 'min', 34);
      await dragHandleTo(page, 'max', 35);

      const patch = page.waitForResponse((r) => r.request().method() === 'PATCH' && r.url().includes('/rest/v1/profiles'));
      await page.getByRole('button', { name: 'שמירה' }).click();
      const res = await patch;
      // Сохранение текущих значений (AC 6), мин ≤ макс (AC 7).
      expect(res.ok()).toBeTruthy();
      expect(res.request().postDataJSON()).toMatchObject({ pref_age_min: 34, pref_age_max: 35 });
      // Подтверждение «נשמר» (AC 9).
      await expect(page.getByText(/נשמר/).first()).toBeVisible();

      // Текущие значения показываются при повторном входе (AC 5).
      await openPrefs(page);
      await expect.poll(() => ageValues(page)).toEqual([34, 35]);
    } finally {
      const back = await page.request.patch(`${api.base}/rest/v1/profiles?id=eq.${api.userId}`, {
        headers: { apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        data: Object.fromEntries(KEYS.map((k) => [k, before[k]])),
        failOnStatusCode: false,
      });
      expect(back.ok(), `возврат предпочтений ${JSON.stringify(before)}`).toBeTruthy();
      await saveSession(page, 'free');
    }
  });

  test('ошибка сохранения видна — «השמירה נכשלה. נסו שוב.», экран остаётся @iphone (#3872fc)', async ({ page }) => {
    await openPrefs(page);
    // Сеть отказывает только на запись — данные не меняются.
    await page.route('**/rest/v1/profiles**', (route) => (route.request().method() === 'GET' ? route.continue() : route.abort()));
    await page.getByRole('radio', { name: 'כולם' }).click();
    await page.getByRole('button', { name: 'שמירה' }).click();
    // Ошибка сохранения видна (AC 11; реджект 28.10), без тёмного пустого экрана — форма на месте.
    await expect(page.getByRole('alert').filter({ hasText: 'השמירה נכשלה. נסו שוב.' })).toBeVisible();
    await expect(page.getByText('מי מעניין אותי')).toBeVisible();
    await expect(page).toHaveURL(/\/prefs/);
    await expect(page.getByText(/^נשמר/)).toHaveCount(0);
    await page.unroute('**/rest/v1/profiles**');
    await saveSession(page, 'free');
  });
});
